INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Marktanalyse immer nur einmalig durchgeführt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßig nötig"}, {"text": "Ja", "correct": false, "because": "Zu statisch"}]'),
